import * as THREE from './vendor/three.module.js';
const $=s=>document.querySelector(s);
const state={mode:'block',floors:4,setback:1,contribution:30,privacy:false,affordable:35,stage:0};
const clamp=n=>Math.max(0,Math.min(100,Math.round(n)));
const actors=[{key:'architect',name:'Architect',icon:'⌑',color:'#527764',priority:'Space, light & a coherent roofline'},{key:'developer',name:'Developer',icon:'↗',color:'#bd7247',priority:'A scheme that can be delivered'},{key:'policy',name:'Planning policy',icon:'▤',color:'#617eaa',priority:'Homes, design quality & local impacts'},{key:'residents',name:'Residents',icon:'⌂',color:'#9580ac',priority:'Daylight, privacy & the street'}];
function model(s){const f=s.mode==='block'?s.floors/3:s.floors,c=s.mode==='room'?0:s.contribution,a=s.mode==='room'?0:s.affordable/5,contextPenalty=s.mode==='block'?Math.max(0,s.floors*3/place.medianHeight-1)*8:0;return [clamp(78+f*7-s.setback*6),clamp(64+f*10-s.setback*8-c*.16-a*1.5-(s.privacy?4:0)),clamp(45+(s.mode!=='room'?12:5)+s.setback*9-f*8+c*.18+a*1.5+(s.privacy?5:0)-contextPenalty*.5),clamp(70-f*15+s.setback*11+(s.privacy?12:0)-contextPenalty)]}
function homes(s){if(s.mode==='room')return 0;return s.mode==='block'?Math.max(1,Math.floor((30-2*s.setback)*(24-s.setback)*s.floors*.8/75)):s.floors*2}
function middle(){let best=null,bestScore=-1;for(let f=1;f<=(state.mode==='block'?12:3);f++)for(let s=0;s<=3;s+=.5)for(let c=0;c<=80;c+=10)for(const p of [false,true])for(const a of (state.mode==='room'?[0]:[state.affordable])){const v={...state,floors:f,setback:s,contribution:state.mode==='room'?0:c,privacy:p,affordable:a};const scores=model(v);const score=Math.min(...scores)+scores.reduce((a,b)=>a+b)/1000;if(score>bestScore){bestScore=score;best=v}}return best}
function feedback(i,n){if(i===2&&place.borough){return place.borough==='Hackney'?'“Local character matters alongside homes.”':place.borough==='Camden'?'“Consider housing and employment together.”':place.borough==='Newham'?'“Check which local plan covers this plot.”':'“Check this council’s adopted policies.”'}return [n>=65?'“Make the roof feel like it belongs.”':'“The setbacks are squeezing the design.”',n>=60?'“There’s a workable scheme here.”':'“The costs are outgrowing the return.”',n>=60?'“The benefits are starting to balance.”':'“We need a stronger case on impacts.”',n>=60?'“Protect our light and our privacy.”':'“This is too much above our homes.”'][i]}
function update(){const scores=model(state);$('#actors').innerHTML=actors.map((a,i)=>`<article class="actor" style="--actor-color:${a.color}"><div class="actor-header"><span class="actor-icon">${a.icon}</span><h3>${a.name}</h3><span class="score">${scores[i]}</span></div><blockquote>${feedback(i,scores[i])}</blockquote><div class="actor-track"><i style="width:${scores[i]}%"></i></div><small>${a.priority}</small></article>`).join('');
$('#floors').value=state.floors;$('#setback').value=state.setback;$('#floors-value').textContent=state.floors;$('#setback-value').textContent=state.setback.toFixed(1)+' m';document.querySelectorAll('[data-mode]').forEach(b=>{b.classList.toggle('selected',b.dataset.mode===state.mode);b.setAttribute('aria-pressed',b.dataset.mode===state.mode)});$('#model-homes').textContent='+'+(state.mode==='room'?state.floors:homes(state));$('#model-home-label').textContent=state.mode==='room'?(state.floors===1?'extra room':'extra rooms'):'estimated homes';$('#affordable').value=state.affordable;$('#affordable-value').textContent=state.affordable+'%';$('.affordable-control').hidden=state.mode==='room';$('#floors').max=state.mode==='block'?12:3;const low=Math.min(...scores);$('#balance-number').textContent=low+'/100';$('#ground-title').textContent=low>=60?'A workable middle ground.':'There’s a gap to bridge.';$('#ground-copy').textContent=low>=60?'Every voice reaches 60 in this illustrative model. Real permission still needs a full assessment.':actors[scores.indexOf(low)].name+' has the lowest support. Adjust the proposal or explore a balanced alternative.';drawChart(scores);updateRoof();}
function drawChart(scores){const target=model(middle()),cx=190,cy=143,r=91;const point=(i,v)=>[cx+Math.sin(i*Math.PI/2)*r*v/100,cy-Math.cos(i*Math.PI/2)*r*v/100];let svg='';for(const v of [25,50,75,100])svg+=`<polygon points="${[0,1,2,3].map(i=>point(i,v).join(',')).join(' ')}" fill="${'none'}" stroke="#dee5da"/>`;svg+=`<polygon points="${[0,1,2,3].map(i=>point(i,100).join(',')).join(' ')}" fill="none" stroke="#dee5da"/>`;for(let i=0;i<4;i++){const p=point(i,100);svg+=`<line x1="${cx}" y1="${cy}" x2="${p[0]}" y2="${p[1]}" stroke="#dee5da"/>`};svg+=`<polygon points="${target.map((n,i)=>point(i,n).join(',')).join(' ')}" fill="#bd724714" stroke="#bd7247" stroke-width="1.5" stroke-dasharray="5 4"/><polygon points="${scores.map((n,i)=>point(i,n).join(',')).join(' ')}" fill="#245e4a28" stroke="#245e4a" stroke-width="2"/>`;scores.forEach((n,i)=>{const p=point(i,n);svg+=`<circle cx="${p[0]}" cy="${p[1]}" r="4" fill="#245e4a"/>`});svg+='<g fill="#5c6b61" font-family="Arial,sans-serif" font-size="12"><text x="190" y="30" text-anchor="middle">Design quality</text><text x="294" y="146">Viability</text><text x="190" y="266" text-anchor="middle">Policy fit</text><text x="78" y="146" text-anchor="end">Neighbour</text><text x="78" y="161" text-anchor="end">amenity</text></g>';$('#radar').innerHTML=svg;$('#radar').setAttribute('aria-label',actors.map((a,i)=>a.name+': '+scores[i]+', middle ground '+target[i]).join('; '));}
let scene,renderer,camera,roof,contextGroup,viewAngle=.75,viewRadius=430,elevation=300,drag=false,lastX=0,lastY=0;
const place={lat:51.546116,lng:-.075137,borough:'Hackney',medianHeight:9,buildings:0,estimated:0};
function box(w,h,d,x,y,z,color,parent=scene){const mesh=new THREE.Mesh(new THREE.BoxGeometry(w,h,d),new THREE.MeshStandardMaterial({color,roughness:.93}));mesh.position.set(x,y,z);mesh.castShadow=true;mesh.receiveShadow=true;if(parent===roof){mesh.material.depthTest=false;mesh.material.transparent=true;mesh.renderOrder=10}parent.add(mesh);return mesh}
function clearGroup(group){if(!group)return;group.traverse(o=>{o.geometry?.dispose();if(o.material)Array.isArray(o.material)?o.material.forEach(m=>m.dispose()):o.material.dispose()});group.clear()}
function initScene(){try{scene=new THREE.Scene();scene.background=new THREE.Color('#e9eee7');scene.fog=new THREE.Fog('#e9eee7',700,1250);camera=new THREE.PerspectiveCamera(42,1,1,2000);renderer=new THREE.WebGLRenderer({antialias:true});renderer.setPixelRatio(Math.min(devicePixelRatio,2));renderer.shadowMap.enabled=true;renderer.shadowMap.type=THREE.PCFSoftShadowMap;renderer.outputColorSpace=THREE.SRGBColorSpace;$('#scene').appendChild(renderer.domElement);scene.add(new THREE.HemisphereLight(0xffffff,0xa9b3a1,1.7));const sun=new THREE.DirectionalLight(0xfffdf5,1.8);sun.position.set(-120,350,220);sun.castShadow=true;sun.shadow.mapSize.set(2048,2048);Object.assign(sun.shadow.camera,{left:-300,right:300,top:300,bottom:-300,far:900});sun.shadow.bias=-.001;scene.add(sun);box(1000,.4,1000,0,-.5,0,'#e2e7dc');const grid=new THREE.GridHelper(700,35,'#d2dbca','#dbe2d5');grid.position.y=.01;scene.add(grid);contextGroup=new THREE.Group();scene.add(contextGroup);roof=new THREE.Group();scene.add(roof);new ResizeObserver(()=>{const el=$('#scene');renderer.setSize(el.clientWidth,el.clientHeight);camera.aspect=el.clientWidth/el.clientHeight;camera.updateProjectionMatrix();render()}).observe($('#scene'));$('#scene').addEventListener('pointerdown',e=>{drag=true;lastX=e.clientX;lastY=e.clientY;e.currentTarget.setPointerCapture(e.pointerId)});$('#scene').addEventListener('pointermove',e=>{if(!drag)return;viewAngle+=(e.clientX-lastX)*.009;elevation=Math.max(70,Math.min(650,elevation+(e.clientY-lastY)*1.2));lastX=e.clientX;lastY=e.clientY;render()});$('#scene').addEventListener('pointerup',()=>drag=false);$('#scene').addEventListener('pointercancel',()=>drag=false);$('#scene').addEventListener('wheel',e=>{e.preventDefault();viewRadius=Math.max(100,Math.min(800,viewRadius+e.deltaY*.3));render()},{passive:false});}catch(e){$('#scene').innerHTML='<div class="model-error"><b>3D needs WebGL.</b><p>Try a browser with WebGL enabled. The map and planning controls remain available.</p></div>';console.error(e)}}
function updateRoof(){if(!roof)return;clearGroup(roof);const block=state.mode==='block',w=block?30:10,d=block?24:12,base=block?0:place.medianHeight;const step=state.setback;const h=state.floors*3;box(w-step*2,h,d-step,0,base+h/2,-step/2,'#2e7154',roof);box(w-step*2+.3,.35,d-step+.3,0,base+h+.2,-step/2,'#779866',roof);for(let f=0;f<state.floors;f++){for(let x=-(w-step*2)/2+2;x<(w-step*2)/2-1;x+=3.5)box(1.7,1.65,.07,x,base+f*3+1.5,(d-step)/2-step/2+.05,'#c7d9be',roof);for(let z=-(d-step)/2+2;z<(d-step)/2-1;z+=3.5)box(.07,1.65,1.7,(w-step*2)/2+.05,base+f*3+1.5,z-step/2,'#b5cbb0',roof)}if(state.privacy)box(w-step*2,.8,.12,0,base+h+.55,(d-step)/2-step/2,'#9aa886',roof);const ring=new THREE.Mesh(new THREE.RingGeometry(22,23,64),new THREE.MeshBasicMaterial({color:'#387151',side:THREE.DoubleSide,transparent:true,opacity:.6}));ring.rotation.x=-Math.PI/2;ring.position.y=.2;roof.add(ring);render()}
