function inRing(x,y,ring){let hit=false;for(let i=0,j=ring.length-1;i<ring.length;j=i++){const a=ring[i],b=ring[j];if((a[1]>y)!==(b[1]>y)&&x<(b[0]-a[0])*(y-a[1])/(b[1]-a[1])+a[0])hit=!hit}return hit}
function inPolygon(x,y,rings){return inRing(x,y,rings[0])&&!rings.slice(1).some(r=>inRing(x,y,r))}
function councilAt(lat,lng){return boundaries?.features.find(f=>(f.geometry.type==='Polygon'?[f.geometry.coordinates]:f.geometry.coordinates).some(p=>inPolygon(lng,lat,p)))}
function xmlContext(xml){const doc=new DOMParser().parseFromString(xml,'application/xml');if(doc.querySelector('parsererror'))throw Error('Map data could not be read.');const nodes=new Map([...doc.querySelectorAll('node')].map(n=>[n.id,{lat:+n.getAttribute('lat'),lon:+n.getAttribute('lon')}]));return{elements:[...doc.querySelectorAll('way')].map(w=>({id:w.id,tags:Object.fromEntries([...w.querySelectorAll('tag')].map(t=>[t.getAttribute('k'),t.getAttribute('v')])),geometry:[...w.querySelectorAll('nd')].map(n=>nodes.get(n.getAttribute('ref'))).filter(Boolean)})).filter(e=>e.tags.building||e.tags.highway)}}
async function selectSite(lat,lng,preset){const feature=councilAt(lat,lng);if(!Number.isFinite(lat)||!Number.isFinite(lng)||!feature){$('#location-status').textContent='Choose coordinates inside a London council boundary.';$('#location-status').classList.add('error');return}const token=++selection;requestController?.abort();$('#middle-ground').disabled=true;$('#location-status').classList.remove('error');Object.assign(place,{lat,lng,borough:feature.properties.name});$('#latitude').value=lat.toFixed(6);$('#longitude').value=lng.toFixed(6);$('#coordinates-heading').textContent=lat.toFixed(5)+', '+lng.toFixed(5);$('#borough-heading').textContent=place.borough;$('#borough-name').textContent=place.borough+' Council';const policy=policies[place.borough];$('#borough-policy').textContent=policy?.text||'This point is in '+place.borough+'. Borough-specific policy has not been reviewed in this prototype. Check the adopted plan, local designations and planning authority before drawing conclusions.';$('#borough-source').textContent=policy?'Read the local policy ↗':'London-wide planning guidance ↗';$('#borough-source').href=policy?.url||'https://www.london.gov.uk/programmes-strategies/planning/london-plan';$('#site-select').value=preset||'custom';if(map){marker.setLatLng([lat,lng]);map.setView([lat,lng],15,{animate:false});boundaryLayer?.setStyle(f=>({color:f.properties.name===place.borough?'#245e4a':'#8b9986',weight:f.properties.name===place.borough?2:1,fillOpacity:f.properties.name===place.borough?.06:.015}))}clearGroup(contextGroup);place.buildings=0;place.medianHeight=9;$('#context-badge').textContent='Loading context';$('#geometry-note').textContent='Loading real mapped surroundings. No previous location is shown. Scores temporarily assume a 9 m context height.';update();showStage();$('#location-status').textContent='Loading mapped buildings and streets…';try{let data;const key=lat.toFixed(5)+','+lng.toFixed(5);if(contextCache.has(key))data=contextCache.get(key);else if(preset){const r=await fetch('context/'+preset+'.json');if(!r.ok)throw Error('Saved neighbourhood data is unavailable.');data=await r.json()}else{if(Date.now()-lastLiveRequest<5000)throw Error('Please wait a few seconds before loading another site.');lastLiveRequest=Date.now();requestController=new AbortController();const timeout=setTimeout(()=>requestController.abort(),25000);try{const bbox=[lng-.0032,lat-.002,lng+.0032,lat+.002].join(',');const r=await fetch('https://api.openstreetmap.org/api/0.6/map?bbox='+bbox,{signal:requestController.signal});if(!r.ok)throw Error('The map service is busy. Try a saved neighbourhood.');data=xmlContext(await r.text())}finally{clearTimeout(timeout)}}if(token!==selection)return;contextCache.set(key,data);contextFromOSM(data);$('#middle-ground').disabled=false;$('#location-status').textContent=place.buildings?place.buildings+' mapped buildings loaded · '+place.borough+'.':'No building footprints found here. Try a nearby point.';if(!place.buildings)$('#location-status').classList.add('error')}catch(e){if(token!==selection)return;$('#middle-ground').disabled=false;$('#location-status').textContent=(e.name==='AbortError'?'The map request timed out. Try a saved neighbourhood.':e.message);$('#location-status').classList.add('error');$('#context-badge').textContent='Context unavailable';$('#geometry-note').textContent='Surroundings unavailable. Scores use an assumed 9 m context height. Choose a saved neighbourhood for mapped context.';render()}}
async function initMap(){try{const r=await fetch('context/london-boroughs.geojson');if(!r.ok)throw Error('Council boundaries are unavailable.');boundaries=await r.json();if(window.L){map=L.map('london-map',{scrollWheelZoom:false}).setView([place.lat,place.lng],14);L.tileLayer('https://tile.openstreetmap.org/{z}/{x}/{y}.png',{maxZoom:19,attribution:'&copy; <a href="https://www.openstreetmap.org/copyright">OpenStreetMap</a> · GLA boroughs'}).addTo(map);boundaryLayer=L.geoJSON(boundaries,{interactive:false,style:{color:'#73876b',weight:1,fillOpacity:.03}}).addTo(map);marker=L.marker([place.lat,place.lng],{title:'Selected proposal location',alt:'Selected proposal location',icon:L.divIcon({className:'map-site-dot',iconSize:[17,17]})}).addTo(map);map.on('click',e=>selectSite(e.latlng.lat,e.latlng.lng));new ResizeObserver(()=>map.invalidateSize()).observe($('#london-map'))}else $('#london-map').textContent='Map unavailable. Select a neighbourhood or use coordinates.';await selectSite(place.lat,place.lng,'dalston')}catch(e){$('#location-status').textContent=e.message;$('#location-status').classList.add('error')}}
$('#site-select').onchange=e=>{const p=presets[e.target.value];if(p)selectSite(p.lat,p.lng,e.target.value)};$('#coordinate-form').onsubmit=e=>{e.preventDefault();selectSite(+$('#latitude').value,+$('#longitude').value)};initMap();
